<x-layouts::app title="Stock Adjustment"><div class="space-y-5"><div><p class="text-xs font-extrabold uppercase tracking-[.18em] text-red-600">Products / Stock</p><h1 class="page-title">Stock Adjustment</h1><p class="page-subtitle">Correct inventory counts with a recorded reason.</p></div><x-flash/><form method="POST" action="{{ route('products.adjustments.store') }}" class="panel" id="adjustment-form" onsubmit="return document.querySelectorAll('.adj-row').length > 0 || (alert('Add at least one product.') && false)">@csrf<x-submission-token/><h2 class="mb-4 text-lg font-extrabold">Create Stock Adjustment</h2><div class="grid gap-4 md:grid-cols-3"><label><span class="label">Store *</span><select name="store_id" class="field" required><option value="">Select store</option>@foreach($stores as $store)<option value="{{ $store->id }}">{{ $store->name }}</option>@endforeach</select></label><label><span class="label">Adjustment Type *</span><select name="direction" class="field" required><option value="increase">Increase</option><option value="decrease">Decrease</option><option value="override">Set Exact Quantity</option></select></label><label><span class="label">Reason / Note</span><input name="note" class="field" placeholder="Stock count correction (optional)"></label></div><div class="mt-6 border-t border-slate-100 pt-4"><h3 class="mb-4 text-sm font-extrabold text-slate-700">Add Products</h3><div class="mb-4 flex items-end gap-2 max-w-4xl"><div class="flex-1"><x-searchable-product-field :products="$products" name="dummy_product_id" id="adjustment-product" placeholder="Search product to add..." /></div><div class="w-32 shrink-0"><span class="label">Quantity *</span><input type="number" id="add-qty" step="any" min="0" class="field h-10 w-full" placeholder="Qty"></div><button type="button" id="btn-add-item" class="btn-secondary h-10 shrink-0">Add Item</button></div><div class="table-wrap mb-4"><table class="data-table"><thead><tr><th>Product</th><th class="w-40">Quantity</